// async function always returns a Promise
async function getNumber() {
  return 42;
}

// This is equivalent to:
// function getNumber() { return Promise.resolve(42); }

getNumber().then(v => console.log(v));  // 42

// Errors become rejected Promises
async function fail() {
  throw new Error("Oops!");
}

fail().catch(e => console.error(e.message));  // "Oops!"

function fetchUser(id) {
  return new Promise(resolve => {
    setTimeout(() => resolve({ id, name: "Alex" }), 100);
  });
}

async function displayUser() {
  console.log("Loading...");
  let user = await fetchUser(1);  // pauses here
  console.log("User: " + user.name);  // "User: Alex"
  console.log("Done!");
}

displayUser();
// Output: Loading... → (100ms) → User: Alex → Done!

async function loadData() {
  try {
    let response = await fetch("https://api.example.com/data");
    let data = await response.json();
    console.log(data);
  } catch (error) {
    console.error("Failed to load:", error.message);
  } finally {
    console.log("Loading complete");
  }
}

// Parallel with individual error handling
async function loadBoth() {
  try {
    let [users, posts] = await Promise.all([
      fetch("/api/users").then(r => r.json()),
      fetch("/api/posts").then(r => r.json())
    ]);
    console.log(users, posts);
  } catch (error) {
    console.error("One request failed:", error);
  }
}

// No async function wrapper needed!
let response = await fetch("https://api.example.com/data");
let data = await response.json();
console.log(data);

// With error handling
try {
  let config = await import("./config.js");
  console.log(config.default);
} catch (error) {
  console.error("Config load failed:", error);
}
